// Написан вручную (запасной путь: MCP-генератор не нашёл seed). Селекторы и поток сверены на живой странице через playwright-cli
// (iPhone 13 Mini, free, 2026-10-29), сам тест не прогонялся — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md 2.4 · кейс .qa/tests/location-map/IND-04.md
// seed: tests/seed.free.geo.spec.ts
// Шит «דייט עכשיו» только открывается и закрывается (Escape) — режим не включается. В конце шаринг выключен.
import { test, expect, type Request, type Response } from '@playwright/test';
import path from 'path';
import { enableSharing, disableSharing } from './map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

const PILL = 'שיתוף מיקום פעיל';
const OFF = 'שיתוף מיקום כבוי';
const isSharePatch = (r: Response) =>
  r.request().method() === 'PATCH' && r.url().includes('/rest/v1/profiles') && (r.request().postData() ?? '').includes('share_location');

test.describe('Индикатор шаринга местоположения', () => {
  test('Выключение с индикатора в шите Date Now: «ביטול» ничего не меняет, «כיבוי שיתוף מיקום» выключает @iphone @data (#5f64d4)', async ({ page }) => {
    try {
      // 1. Выключить, если включён; включить
      await disableSharing(page);
      await enableSharing(page);

      // 2. Шит «דייט עכשיו» → пилюля «שיתוף מיקום פעיל» → диалог «לכבות את שיתוף המיקום?» (AC 3)
      await page.getByRole('button', { name: 'דייט עכשיו' }).first().click();
      const sheet = page.getByRole('dialog').filter({ hasText: 'פנוי/ה לדייט עכשיו?' });
      await expect(sheet).toBeVisible();
      const sheetPill = sheet.getByRole('button', { name: PILL });
      await sheetPill.click();
      const question = page.getByText('לכבות את שיתוף המיקום?');
      await expect(question).toBeVisible();
      await expect(page.getByRole('button', { name: 'כיבוי שיתוף מיקום' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'ביטול' })).toBeVisible();

      // 3. «ביטול» — диалог закрыт, PATCH share_location нет, пилюля на месте
      const sharePatches: Request[] = [];
      const onReq = (r: Request) => {
        if (r.method() === 'PATCH' && r.url().includes('/rest/v1/profiles') && (r.postData() ?? '').includes('share_location')) sharePatches.push(r);
      };
      page.on('request', onReq);
      await page.getByRole('button', { name: 'ביטול' }).click();
      await expect(question).toBeHidden();
      await expect(sheet).toBeVisible();
      await expect(sheetPill).toBeVisible();
      page.off('request', onReq);
      expect(sharePatches, 'PATCH share_location после «ביטול»').toHaveLength(0);

      // 4. Снова пилюля → «כיבוי שיתוף מיקום» → PATCH share_location=false, 2xx; пилюли нет ни в шите, ни на карте
      await sheetPill.click();
      await expect(question).toBeVisible();
      const patch = page.waitForResponse(isSharePatch);
      await page.getByRole('button', { name: 'כיבוי שיתוף מיקום' }).click();
      const res = await patch;
      expect(res.ok()).toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ share_location: false });
      await expect(question).toBeHidden();
      await expect(sheet.getByText(PILL, { exact: true })).toHaveCount(0);

      // 5. Закрыть шит; на /map — «שיתוף מיקום כבוי», пилюли нет (AC 2; F-15 «באופן מיידי»)
      await page.keyboard.press('Escape');
      await expect(sheet).toBeHidden();
      await expect(page.getByText(OFF, { exact: true })).toBeVisible();
      await expect(page.getByText(PILL, { exact: true })).toHaveCount(0);
    } finally {
      // Очистка: если шаринг остался включённым — выключить
      await disableSharing(page).catch(() => {});
      await saveSession(page, 'free');
    }
  });
});
